(4034418, 577515, 41675, '<td valign="top">I like the soft dream-like quality your iage evokes. Sweet looking dog - but then again, they usually are when they''re asleep. Lol</td>', 'I like the soft dream-like quality your iage evokes. Sweet looking dog - but then again, they usually are when they''re asleep. Lol', '2007-08-27 23:47:01.000000', NULL, 1),
(4034420, 577317, 41675, '<td valign="top">Nice fill the frame. I like the texture of the feathers.</td>', 'Nice fill the frame. I like the texture of the feathers.', '2007-08-27 23:47:35.000000', NULL, 1),
(4034423, 577681, 41675, '<td valign="top">I wish there had been less dust/dirt on the rocks. I like the lighting and all the different colors.</td>', 'I wish there had been less dust/dirt on the rocks. I like the lighting and all the different colors.', '2007-08-27 23:48:18.000000', NULL, 1),
(4034424, 576828, 41675, '<td valign="top">I like it. Good color values. Best of luck in the challenge. 10</td>', 'I like it. Good color values. Best of luck in the challenge. 10', '2007-08-27 23:49:01.000000', NULL, 1),
(4034426, 576059, 41675, '<td valign="top">Very sweet and riveting image. I like it.</td>', 'Very sweet and riveting image. I like it.', '2007-08-27 23:49:26.000000', NULL, 1),
(4034431, 575731, 41675, '<td valign="top">Eww - kind of gross upon first look..and second look too, but its different and interesting and definitely fills the frame. Good luck in the challenge.</td>', 'Eww - kind of gross upon first look..and second look too, but its different and interesting and definitely fills the frame. Good luck in the challenge.', '2007-08-27 23:50:41.000000', NULL, 1),
