(4034440, 577695, 41675, '<td valign="top">Aww - cute little guy. I like the eye.</td>', 'Aww - cute little guy. I like the eye.', '2007-08-27 23:53:15.000000', NULL, 1),
(4034443, 577623, 41675, '<td valign="top">Pretty stained glass, I like the colors.</td>', 'Pretty stained glass, I like the colors.', '2007-08-27 23:54:54.000000', NULL, 1),
