INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4034632, 577212, 76430, '<td valign="top">It''s just an OOF picture of a fist.  It does fill the frame pretty much, but I don''t get it.</td>', 'It''s just an OOF picture of a fist.  It does fill the frame pretty much, but I don''t get it.', '2007-08-28 01:36:21.000000', NULL, 1),
(4034643, 577747, 33672, '<td valign="top">really well done.</td>', 'really well done.', '2007-08-28 01:47:11.000000', NULL, 1),
(4034645, 577755, 33672, '<td valign="top">Really nice work. I like the tones and the crop. The DOF helps isolate the subject nicely.</td>', 'Really nice work. I like the tones and the crop. The DOF helps isolate the subject nicely.', '2007-08-28 01:49:14.000000', NULL, 1),
(4034648, 577426, 33672, '<td valign="top">Great capture, Very crisp.</td>', 'Great capture, Very crisp.', '2007-08-28 01:49:57.000000', NULL, 1),
(4034655, 577365, 76430, '<td valign="top">If this was in focus it would be much better.  It does meet the challenge, and at first glance looks nasty!</td>', 'If this was in focus it would be much better.  It does meet the challenge, and at first glance looks nasty!', '2007-08-28 01:52:27.000000', NULL, 1),
