(4038639, 577584, 68573, '<td valign="top">nice portrait with amazing eyes</td>', 'nice portrait with amazing eyes', '2007-08-29 13:37:33.000000', NULL, 1),
(4038792, 575582, 66952, '<td valign="top">Lots of cat pics in this challenge, but this is one of the better ones. The mix of light and shadow is lovely.</td>', 'Lots of cat pics in this challenge, but this is one of the better ones. The mix of light and shadow is lovely.', '2007-08-29 14:16:00.000000', NULL, 1),
(4038815, 577712, 66952, '<td valign="top">A frog that likes to play dress up? Cool!</td>', 'A frog that likes to play dress up? Cool!', '2007-08-29 14:28:46.000000', NULL, 1),
(4038818, 577705, 66952, '<td valign="top">I think he''s looking at you like he''s hungry. The tight crop works well. The shadows are a bit harsh, but the rest is great.</td>', 'I think he''s looking at you like he''s hungry. The tight crop works well. The shadows are a bit harsh, but the rest is great.', '2007-08-29 14:30:38.000000', NULL, 1),
(4039103, 577698, 83453, '<td valign="top">This is a great photo!</td>', 'This is a great photo!', '2007-08-29 16:11:06.000000', NULL, 1),
(4039178, 577665, 56828, '<td valign="top">This does not meet the challenge in my opinion.  The challenge was to only have your subject in the frame....which would be no background or grass, etc.</td>', 'This does not meet the challenge in my opinion.  The challenge was to only have your subject in the frame....which would be no background or grass, etc.', '2007-08-29 16:34:01.000000', NULL, 1),
(4039184, 577537, 56828, '<td valign="top">There is slightly too much yellow under and around the left eye.  it looks unnatural.</td>', 'There is slightly too much yellow under and around the left eye.  it looks unnatural.', '2007-08-29 16:35:03.000000', NULL, 1),
(4039188, 576689, 56828, '<td valign="top">It''s kinda weird, but pleasing.</td>', 'It''s kinda weird, but pleasing.', '2007-08-29 16:35:41.000000', NULL, 1),
(4039199, 577652, 56828, '<td valign="top">Great try at being out of the box...I just don''t think it quite got there.  If the trees weren''t seen on the side i would have given it the benefit of doubt.</td>', 'Great try at being out of the box...I just don''t think it quite got there.  If the trees weren''t seen on the side i would have given it the benefit of doubt.', '2007-08-29 16:38:16.000000', NULL, 1),
(4039257, 576873, 66952, '<td valign="top">Great job getting in tight to the face! The lighting is a bit harsh, but otherwise, a great capture.</td>', 'Great job getting in tight to the face! The lighting is a bit harsh, but otherwise, a great capture.', '2007-08-29 16:49:22.000000', NULL, 1),
(4039271, 577688, 66952, '<td valign="top">Beautiful. Definitely. Great light, composition, everything. But it doesn''t really meet my interpretation of ''fill the frame''.</td>', 'Beautiful. Definitely. Great light, composition, everything. But it doesn''t really meet my interpretation of ''fill the frame''.', '2007-08-29 16:51:27.000000', NULL, 1),
(4039282, 577644, 66952, '<td valign="top">It''s a lovely yellow rose. I like the water droplets and the composition. I think the lighting really lets you down. It''s too harsh and contrasty. You might try shooting on a cloudy day, or using something to shade it.</td>', 'It''s a lovely yellow rose. I like the water droplets and the composition. I think the lighting really lets you down. It''s too harsh and contrasty. You might try shooting on a cloudy day, or using something to shade it.', '2007-08-29 16:56:02.000000', NULL, 1),
(4039308, 577652, 66952, '<td valign="top">Nice and graphic, and an interesting perspective. Could be a little bit sharper.</td>', 'Nice and graphic, and an interesting perspective. Could be a little bit sharper.', '2007-08-29 17:07:55.000000', NULL, 1),
(4039320, 577753, 66952, '<td valign="top">This is a great idea, but would be better if the ball was in focus, since the ball is the main subject.</td>', 'This is a great idea, but would be better if the ball was in focus, since the ball is the main subject.', '2007-08-29 17:14:18.000000', NULL, 1),
(4039501, 575391, 52981, '<td valign="top">tough one... beautiful photo!!  Im not so sure it fills the frame though.  Would be 9, but I have to go 6.  Great shot anyhow!!!</td>', 'tough one... beautiful photo!!  Im not so sure it fills the frame though.  Would be 9, but I have to go 6.  Great shot anyhow!!!', '2007-08-29 18:43:56.000000', NULL, 1),
(4039528, 575978, 52981, '<td valign="top">oh my god!!! what is that?</td>', 'oh my god!!! what is that?', '2007-08-29 18:56:20.000000', NULL, 1),
(4039612, 576198, 19786, '<td valign="top">Focus and color use is outstanding well centered</td>', 'Focus and color use is outstanding well centered', '2007-08-29 19:39:41.000000', NULL, 1),
(4039617, 577698, 19786, '<td valign="top">Great color and use of contrast. Very sharp focus</td>', 'Great color and use of contrast. Very sharp focus', '2007-08-29 19:41:29.000000', NULL, 1),
