(4039971, 577770, 73250, '<td valign="top">I wish the focus was on the eyes and not the nose. Fits the challenge well.</td>', 'I wish the focus was on the eyes and not the nose. Fits the challenge well.', '2007-08-29 21:50:04.000000', NULL, 1),
