(4042644, 577776, 19978, '<td valign="top">Nicely done and meets the challenge well enough, but the photo lacks any real visual or emotional impact.</td>', 'Nicely done and meets the challenge well enough, but the photo lacks any real visual or emotional impact.', '2007-08-30 22:00:14.000000', NULL, 1),
(4042648, 577771, 42254, '<td valign="top">Great closeup--white/gray in hair leads to those soulful eyes!</td>', 'Great closeup--white/gray in hair leads to those soulful eyes!', '2007-08-30 22:00:49.000000', NULL, 1),
(4042651, 577385, 42254, '<td valign="top">Nice color and composition effects.</td>', 'Nice color and composition effects.', '2007-08-30 22:01:33.000000', NULL, 1),
(4042653, 577444, 19978, '<td valign="top">Nice use of framing, but it ultimately comes across as a routine family snap. Should be meaningful to family though. A keeper as family shots go.</td>', 'Nice use of framing, but it ultimately comes across as a routine family snap. Should be meaningful to family though. A keeper as family shots go.', '2007-08-30 22:01:42.000000', NULL, 1),
(4042660, 576542, 19978, '<td valign="top">A good idea but ultimately comes across as a little too ordinary and uninspiring. Musical instruments, especially woods, IMO, have lots of potential. Look for more lines, curves and points of interest.</td>', 'A good idea but ultimately comes across as a little too ordinary and uninspiring. Musical instruments, especially woods, IMO, have lots of potential. Look for more lines, curves and points of interest.', '2007-08-30 22:04:09.000000', NULL, 1),
