(4044820, 576873, 33672, '<td valign="top">Idea is a ribbon winner. Levels need an adjustment as light seems a bit harsh. Still a great face to face capture.</td>', 'Idea is a ribbon winner. Levels need an adjustment as light seems a bit harsh. Still a great face to face capture.', '2007-08-31 21:58:51.000000', NULL, 1),
