(4045021, 577673, 52169, '<td valign="top">Love, love, love it! A portrait that shows true skin tone. Beautiful close up and wonderful feeling. 10</td>', 'Love, love, love it! A portrait that shows true skin tone. Beautiful close up and wonderful feeling. 10', '2007-08-31 23:40:38.000000', NULL, 1),
(4045025, 576828, 79720, '<td valign="top">Perfect DoF...great grey tones. Top 5 image.</td>', 'Perfect DoF...great grey tones. Top 5 image.', '2007-08-31 23:42:33.000000', NULL, 1),
(4045026, 577664, 79720, '<td valign="top">How Warhol! I like it - 8</td>', 'How Warhol! I like it - 8', '2007-08-31 23:43:17.000000', NULL, 1),
(4045064, 576873, 7485, '<td valign="top">Great composition, too bad about the blown highlights</td>', 'Great composition, too bad about the blown highlights', '2007-09-01 00:26:46.000000', NULL, 1),
(4045065, 577723, 7485, '<td valign="top">Lovely image, wrong challenge</td>', 'Lovely image, wrong challenge', '2007-09-01 00:27:40.000000', NULL, 1),
(4045069, 577688, 7485, '<td valign="top">Great lighting and interesting subject, but not a good fit for this challenge</td>', 'Great lighting and interesting subject, but not a good fit for this challenge', '2007-09-01 00:30:07.000000', NULL, 1),
(4045086, 577243, 7485, '<td valign="top">Lovely model, but you need to be far more subtle about skin smoothing. Especially at such close range, where you expect to always see a little skin texture, no matter how smooth the skin. You''ve got the right idea about not smoothing eyes, eyebrows and lips, but you''re just using too much blur everywhere else. And that frame is just a distraction.</td>', 'Lovely model, but you need to be far more subtle about skin smoothing. Especially at such close range, where you expect to always see a little skin texture, no matter how smooth the skin. You''ve got the right idea about not smoothing eyes, eyebrows and lips, but you''re just using too much blur everywhere else. And that frame is just a distraction.', '2007-09-01 00:35:26.000000', NULL, 1),
(4045090, 577156, 7485, '<td valign="top">That''s one of the best flower macros I''ve seen for long time. Very sensual!</td>', 'That''s one of the best flower macros I''ve seen for long time. Very sensual!', '2007-09-01 00:36:20.000000', NULL, 1),
(4045093, 577665, 7485, '<td valign="top">Great environmental portrait, but not a good fit with the challenge.</td>', 'Great environmental portrait, but not a good fit with the challenge.', '2007-09-01 00:37:07.000000', NULL, 1),
(4045100, 577673, 7485, '<td valign="top">Great portrait, with excellent texture. I might have toned down the highlights a tad, and filled the frame a bit more, but those are minor quibbles.</td>', 'Great portrait, with excellent texture. I might have toned down the highlights a tad, and filled the frame a bit more, but those are minor quibbles.', '2007-09-01 00:40:03.000000', NULL, 1),
(4045104, 577180, 7485, '<td valign="top">I like the expression and face paint, but she really isn''t very close to filling the frame. And speaking of, that frame''s got to go...</td>', 'I like the expression and face paint, but she really isn''t very close to filling the frame. And speaking of, that frame''s got to go...', '2007-09-01 00:42:09.000000', NULL, 1),
