(4048207, 576059, 66267, '<td valign="top">7, could have filled up a bit more of the frame.</td>', '7, could have filled up a bit more of the frame.', '2007-09-01 21:47:11.000000', NULL, 1),
(4048208, 577791, 66267, '<td valign="top">frightening...</td>', 'frightening...', '2007-09-01 21:47:39.000000', NULL, 1),
(4048249, 577772, 51802, '<td valign="top">I love how there is just the slightest hint of color here!  This is wonderful!  Adding this to my favorites!</td>', 'I love how there is just the slightest hint of color here!  This is wonderful!  Adding this to my favorites!', '2007-09-01 22:00:03.000000', NULL, 1),
(4048255, 577770, 51802, '<td valign="top">The DoF is just a little too shallow.  The bridge of the cat''s nose is in perfect focus, but the eyes are a bit blurry.  Stetting down you aperture 1 stop would probably been enough to fix this.</td>', 'The DoF is just a little too shallow.  The bridge of the cat''s nose is in perfect focus, but the eyes are a bit blurry.  Stetting down you aperture 1 stop would probably been enough to fix this.', '2007-09-01 22:02:55.000000', NULL, 1),
(4048258, 577541, 51802, '<td valign="top">The flash is really harsh on this shot and has caused a bluish tint to the picture.  A little color adjustment would have fixed this.</td>', 'The flash is really harsh on this shot and has caused a bluish tint to the picture.  A little color adjustment would have fixed this.', '2007-09-01 22:03:52.000000', NULL, 1),
(4048263, 577730, 51802, '<td valign="top">The flash reflection in the glass is a major distraction.  More indirect lighting would have helped a lot.</td>', 'The flash reflection in the glass is a major distraction.  More indirect lighting would have helped a lot.', '2007-09-01 22:05:14.000000', NULL, 1),
(4048264, 577676, 51802, '<td valign="top">Wonderful lighting!</td>', 'Wonderful lighting!', '2007-09-01 22:05:29.000000', NULL, 1),
(4048270, 577688, 51802, '<td valign="top">Stunning picture!  ...but this does not meet the challenge.</td>', 'Stunning picture!  ...but this does not meet the challenge.', '2007-09-01 22:08:15.000000', NULL, 1),
(4048278, 577666, 51802, '<td valign="top">This would have worked much better if all of her mouth were visible, or none of it.</td>', 'This would have worked much better if all of her mouth were visible, or none of it.', '2007-09-01 22:09:47.000000', NULL, 1),
(4048395, 576478, 76430, '<td valign="top">This is just too postprocessed for me.  It looks like it''s solarized or converted to pencil drawing or something.  Good composition though.</td>', 'This is just too postprocessed for me.  It looks like it''s solarized or converted to pencil drawing or something.  Good composition though.', '2007-09-01 23:08:27.000000', NULL, 1),
(4048402, 577456, 76430, '<td valign="top">Good shot, but a little too shallow DOF for me.  I''d like to see the "nose" sharper.  Good coloring.  Is this a crab or some insect?  Good title too.</td>', 'Good shot, but a little too shallow DOF for me.  I''d like to see the "nose" sharper.  Good coloring.  Is this a crab or some insect?  Good title too.', '2007-09-01 23:11:17.000000', NULL, 1),
(4048408, 577243, 76430, '<td valign="top">Good shot.  The pearl earring is OOF, and it is half of the title.  Stop it down a bit more and adjust the shutter speed.  You got good lighting and exposure.</td>', 'Good shot.  The pearl earring is OOF, and it is half of the title.  Stop it down a bit more and adjust the shutter speed.  You got good lighting and exposure.', '2007-09-01 23:13:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4048418, 577499, 76430, '<td valign="top">Very good detail.  Maybe it''s just me, and I keep commenting on this, but I''d like to see the nose in focus also.</td>', 'Very good detail.  Maybe it''s just me, and I keep commenting on this, but I''d like to see the nose in focus also.', '2007-09-01 23:14:51.000000', NULL, 1),
(4048434, 577706, 76430, '<td valign="top">Starfish and other stuff?  Good composition.  I''d like to see the lower left starfish in focus.</td>', 'Starfish and other stuff?  Good composition.  I''d like to see the lower left starfish in focus.', '2007-09-01 23:18:45.000000', NULL, 1),
(4048435, 577717, 76430, '<td valign="top">Excellent shot with very good sharpness on the head.</td>', 'Excellent shot with very good sharpness on the head.', '2007-09-01 23:19:13.000000', NULL, 1),
(4048439, 576913, 76430, '<td valign="top">Those eyes really jump out at you and grab your attention.</td>', 'Those eyes really jump out at you and grab your attention.', '2007-09-01 23:20:23.000000', NULL, 1),
(4048456, 577688, 76430, '<td valign="top">17 Mile Drive in Carmel.  This is a beautiful drive.  The Lone Cypress is a highly photographed scene.  You did very well with the coloring of the rocks and water and sharpness.</td>', '17 Mile Drive in Carmel.  This is a beautiful drive.  The Lone Cypress is a highly photographed scene.  You did very well with the coloring of the rocks and water and sharpness.', '2007-09-01 23:23:41.000000', NULL, 1),
(4048472, 576164, 76430, '<td valign="top">It''s not especially sharp, but it''s very creative.</td>', 'It''s not especially sharp, but it''s very creative.', '2007-09-01 23:29:03.000000', NULL, 1),
(4048478, 577515, 76430, '<td valign="top">Whether it''s intentional or not it looks like a dream vision, with soft focus.  It doesn''t look very well composed to me, sort of snapshot like.</td>', 'Whether it''s intentional or not it looks like a dream vision, with soft focus.  It doesn''t look very well composed to me, sort of snapshot like.', '2007-09-01 23:31:10.000000', NULL, 1),
(4048481, 577597, 76430, '<td valign="top">Do you mean a bug ON me?  If so, good title.  Creepy looking spider in very sharp focus.</td>', 'Do you mean a bug ON me?  If so, good title.  Creepy looking spider in very sharp focus.', '2007-09-01 23:32:37.000000', NULL, 1),
(4048486, 577726, 76430, '<td valign="top">Very creative and sharp.  I''m not sure your subject fills the frame.  Still a very good shot, so I''ll give you an 8.</td>', 'Very creative and sharp.  I''m not sure your subject fills the frame.  Still a very good shot, so I''ll give you an 8.', '2007-09-01 23:35:54.000000', NULL, 1),
(4048491, 577527, 76430, '<td valign="top">Just a snapshot of a dog''s face.  I don''t see anything very interesting here.  Maybe if Sissy was looking more at your camera.</td>', 'Just a snapshot of a dog''s face.  I don''t see anything very interesting here.  Maybe if Sissy was looking more at your camera.', '2007-09-01 23:37:09.000000', NULL, 1),
(4048497, 577060, 76430, '<td valign="top">She looks angry or disinterested.  The lips and cheeks look a bit off.  Good attempt.</td>', 'She looks angry or disinterested.  The lips and cheeks look a bit off.  Good attempt.', '2007-09-01 23:38:34.000000', NULL, 1),
(4048501, 576393, 76430, '<td valign="top">Too small and not sharp enough.</td>', 'Too small and not sharp enough.', '2007-09-01 23:39:37.000000', NULL, 1),
(4048505, 576888, 76430, '<td valign="top">The streak of light is unfortunate.  Her eyes appear to be too far to the side.  Good picture otherwise.</td>', 'The streak of light is unfortunate.  Her eyes appear to be too far to the side.  Good picture otherwise.', '2007-09-01 23:40:45.000000', NULL, 1),
(4048511, 575978, 76430, '<td valign="top">What is this, a mollusk?  Something with tusks?  Good perspective.  It could stand to be sharper.</td>', 'What is this, a mollusk?  Something with tusks?  Good perspective.  It could stand to be sharper.', '2007-09-01 23:42:07.000000', NULL, 1),
(4048516, 577086, 76430, '<td valign="top">Delicious looking, very fresh, crisp and sharp.</td>', 'Delicious looking, very fresh, crisp and sharp.', '2007-09-01 23:43:04.000000', NULL, 1),
(4048548, 577546, 76430, '<td valign="top">Are you sure it''s not a view from the past?</td>', 'Are you sure it''s not a view from the past?', '2007-09-01 23:54:09.000000', NULL, 1),
(4048564, 576930, 76430, '<td valign="top">The flash is too harsh and the nose isn''t as sharp as I''d like to see it.</td>', 'The flash is too harsh and the nose isn''t as sharp as I''d like to see it.', '2007-09-02 00:00:21.000000', NULL, 1),
(4048568, 577180, 76430, '<td valign="top">This could be a winner.  I don''t really like the frame cutting into the subject.  9</td>', 'This could be a winner.  I don''t really like the frame cutting into the subject.  9', '2007-09-02 00:01:30.000000', NULL, 1),
(4048570, 576487, 76430, '<td valign="top">Excellent picture and title.  Did you rip apart a disk drive to get this?  I like the reflection of the sky making the double-entendre of the title.  Excellent macro, composition and sharpness as well as getting the close-up as well as the clouds in focus.  9</td>', 'Excellent picture and title.  Did you rip apart a disk drive to get this?  I like the reflection of the sky making the double-entendre of the title.  Excellent macro, composition and sharpness as well as getting the close-up as well as the clouds in focus.  9', '2007-09-02 00:01:37.000000', NULL, 1),
(4048571, 577296, 76430, '<td valign="top">It looks like George Carlin.  I guess you took a picture, printed it, took a picture including that picture, etc, etc.  That''s a pretty sissy looking watering can.  Very creative view of the challenge.  Nitpik, it''s oops, not opps, but since this isn''t a spelling challenge, 8.</td>', 'It looks like George Carlin.  I guess you took a picture, printed it, took a picture including that picture, etc, etc.  That''s a pretty sissy looking watering can.  Very creative view of the challenge.  Nitpik, it''s oops, not opps, but since this isn''t a spelling challenge, 8.', '2007-09-02 00:01:41.000000', NULL, 1),
(4048942, 577546, 39430, '<td valign="top">Nice artistic composition.  The burnt-out highlights on the left (possibly the flash reflection?) are a little distracting.</td>', 'Nice artistic composition.  The burnt-out highlights on the left (possibly the flash reflection?) are a little distracting.', '2007-09-02 01:58:23.000000', NULL, 1),
(4048945, 577747, 39430, '<td valign="top">Nice glamour shot, although it would benefit from a little extra sharpening to make it really crisp.  Good backlighting on the hair.</td>', 'Nice glamour shot, although it would benefit from a little extra sharpening to make it really crisp.  Good backlighting on the hair.', '2007-09-02 01:59:57.000000', NULL, 1),
(4048948, 577736, 39430, '<td valign="top">Well, the frame is full, but that thing is UGLY!  :)</td>', 'Well, the frame is full, but that thing is UGLY!  :)', '2007-09-02 02:01:48.000000', NULL, 1),
(4048949, 577130, 39430, '<td valign="top">It looks a little soft, maybe from noise reduction?  Nice lines and patterns.</td>', 'It looks a little soft, maybe from noise reduction?  Nice lines and patterns.', '2007-09-02 02:02:46.000000', NULL, 1),
(4048953, 577778, 39430, '<td valign="top">Nice frame filling, and a great image.  I try to give some constructive criticism, but there''s nothing to comment on in this image.  I love the soft tones and crisp focus.  Well done.</td>', 'Nice frame filling, and a great image.  I try to give some constructive criticism, but there''s nothing to comment on in this image.  I love the soft tones and crisp focus.  Well done.', '2007-09-02 02:03:53.000000', NULL, 1),
(4048957, 577673, 39430, '<td valign="top">Excellent work on the lighting.  Just a tad burnt in the highlights, but great contrasts, and nice sharp focus.</td>', 'Excellent work on the lighting.  Just a tad burnt in the highlights, but great contrasts, and nice sharp focus.', '2007-09-02 02:05:33.000000', NULL, 1),
(4048958, 577755, 39430, '<td valign="top">It''s a little misty, possibly from the sepia toning filter.</td>', 'It''s a little misty, possibly from the sepia toning filter.', '2007-09-02 02:06:41.000000', NULL, 1),
(4048959, 577538, 39430, '<td valign="top">Nice colours.  Could do with a little more contrast.</td>', 'Nice colours.  Could do with a little more contrast.', '2007-09-02 02:07:19.000000', NULL, 1),
(4048960, 576197, 39430, '<td valign="top">There''s a lot of clutter that could be cut out to fit the challenge better, and the reflection in the window is a little distracting.  Nice colours and sharp image though.</td>', 'There''s a lot of clutter that could be cut out to fit the challenge better, and the reflection in the window is a little distracting.  Nice colours and sharp image though.', '2007-09-02 02:09:27.000000', NULL, 1),
(4048963, 577601, 39430, '<td valign="top">The frame is full, but there''s no subject!</td>', 'The frame is full, but there''s no subject!', '2007-09-02 02:11:38.000000', NULL, 1),
(4048965, 577544, 39430, '<td valign="top">BW loses it''s impact if there is too much detail.  Sometimes it helps to leave a little colour in, or recompose to include blocks of light and dark colour.</td>', 'BW loses it''s impact if there is too much detail.  Sometimes it helps to leave a little colour in, or recompose to include blocks of light and dark colour.', '2007-09-02 02:13:24.000000', NULL, 1),
(4048967, 577721, 39430, '<td valign="top">Nice soft tones, but it would be better if the dot thing was in really crisp focus.</td>', 'Nice soft tones, but it would be better if the dot thing was in really crisp focus.', '2007-09-02 02:15:16.000000', NULL, 1),
(4048968, 576209, 39430, '<td valign="top">Ah, someone is getting a good run for their costume, in here, and in the free study.  :)  This image looks like it''s had very strong noise reduction, and sections of the skin are very unnaturally smoothed.  The tone-mapping works well, but perhaps a touch overdone here.</td>', 'Ah, someone is getting a good run for their costume, in here, and in the free study.  :)  This image looks like it''s had very strong noise reduction, and sections of the skin are very unnaturally smoothed.  The tone-mapping works well, but perhaps a touch overdone here.', '2007-09-02 02:17:59.000000', NULL, 1),
(4048970, 576984, 39430, '<td valign="top">Interesting take on filling the frame.  It''s a great image, and really emphasises the size of the falls.</td>', 'Interesting take on filling the frame.  It''s a great image, and really emphasises the size of the falls.', '2007-09-02 02:19:32.000000', NULL, 1),
(4048971, 577698, 39430, '<td valign="top">She''s not really filling the frame, but it''s a nice image.</td>', 'She''s not really filling the frame, but it''s a nice image.', '2007-09-02 02:21:03.000000', NULL, 1),
(4049007, 577701, 39430, '<td valign="top">There''s a lot of detail lost in the skin, possibly from noise reduction.  Nice composition though, and certainly fits the challenge.</td>', 'There''s a lot of detail lost in the skin, possibly from noise reduction.  Nice composition though, and certainly fits the challenge.', '2007-09-02 02:48:00.000000', NULL, 1),
(4049010, 577144, 39430, '<td valign="top">Too dark, I think.  Draganized?</td>', 'Too dark, I think.  Draganized?', '2007-09-02 02:50:37.000000', NULL, 1),
(4049012, 576316, 39430, '<td valign="top">Nice image, although not quite sharp.</td>', 'Nice image, although not quite sharp.', '2007-09-02 02:51:34.000000', NULL, 1),
(4049014, 577436, 39430, '<td valign="top">Not quite sharp, possibly from noise reduction?</td>', 'Not quite sharp, possibly from noise reduction?', '2007-09-02 02:52:51.000000', NULL, 1),
(4049015, 576573, 39430, '<td valign="top">I like the colour treatment - makes the eyes really stand out.</td>', 'I like the colour treatment - makes the eyes really stand out.', '2007-09-02 02:53:40.000000', NULL, 1),
(4049021, 577666, 39430, '<td valign="top">Softer lighting might help smooth the skin.  Lower lighting would also help to bring the eyes out of shadow.</td>', 'Softer lighting might help smooth the skin.  Lower lighting would also help to bring the eyes out of shadow.', '2007-09-02 02:55:13.000000', NULL, 1),
(4049027, 577575, 39430, '<td valign="top">Nice collection.  The dark left corner is a little annoying.</td>', 'Nice collection.  The dark left corner is a little annoying.', '2007-09-02 02:57:39.000000', NULL, 1),
(4049046, 577385, 39430, '<td valign="top">I''m not a fan of flower photos, but I love the dreamy look here.</td>', 'I''m not a fan of flower photos, but I love the dreamy look here.', '2007-09-02 03:05:09.000000', NULL, 1),
(4049047, 576347, 39430, '<td valign="top">Would be better if the DOF was wider</td>', 'Would be better if the DOF was wider', '2007-09-02 03:05:30.000000', NULL, 1),
(4049063, 577213, 39430, '<td valign="top">This is cool.  I''m sure I''ve seen a photo of this somewhere this week, but I can''t remember where.</td>', 'This is cool.  I''m sure I''ve seen a photo of this somewhere this week, but I can''t remember where.', '2007-09-02 03:11:51.000000', NULL, 1),
