(4051061, 577537, 62895, '<td valign="top">Great expression and color hue. The slight yellow overcast enhances the blonde hair nicely. There does seem to be a little bit of a line under the left eye, starting at the inside corner. 9</td>', 'Great expression and color hue. The slight yellow overcast enhances the blonde hair nicely. There does seem to be a little bit of a line under the left eye, starting at the inside corner. 9', '2007-09-02 20:54:23.000000', NULL, 1),
(4051064, 576828, 62895, '<td valign="top">The square composition really works for me. The processing is very nice as well. The horn totally makes the shot in my opinion. 9<br/><br/><i>Message edited by author 2007-09-03 18:30:31.</i></td>', 'The square composition really works for me. The processing is very nice as well. The horn totally makes the shot in my opinion. 9', '2007-09-02 20:55:20.000000', '2007-09-03 19:30:31.000000', 1),
(4051065, 577618, 62895, '<td valign="top">Usually I think of filling the frame as the subject taking up the whole frame with little or no background showing. You have found a unique way filling the frame and yet letting background into the photo as well. Nicely done! 8</td>', 'Usually I think of filling the frame as the subject taking up the whole frame with little or no background showing. You have found a unique way filling the frame and yet letting background into the photo as well. Nicely done! 8', '2007-09-02 20:55:32.000000', NULL, 1),
